// FluidEDA parse worker driver (Phase 2b STEP 2).
//
// Runs a core-only wasm module (worker.js + worker_bg.wasm, generated by
// scripts/build_worker.sh) in a Web Worker. Receives GDS bytes from the main
// thread, parses them off the main thread, and transfers the serialized CellDb
// columns back as zero-copy ArrayBuffers. The main thread terminates this worker
// after `done`, reclaiming its ~0.8 GB parse memory.
//
// This is a classic (no-modules) worker: importScripts defines the global
// `wasm_bindgen` init function; after init, `wasm_bindgen.parse` is callable.

importScripts('worker.js');

// Kick off wasm instantiation immediately; message handling awaits it.
const ready = wasm_bindgen('worker_bg.wasm');

self.onmessage = async (e) => {
  const msg = e.data || {};
  if (msg.type !== 'parse') return;
  try {
    await ready;
    // msg.bytes is a transferred ArrayBuffer (moved from the main thread).
    const bytes = new Uint8Array(msg.bytes);
    const result = wasm_bindgen.parse(bytes); // the heavy work, off the main thread

    const coords = result.coords;
    const starts = result.starts;
    const layers = result.layers;
    const meta = result.meta;
    const layer_set = result.layer_set;
    const world_bbox = result.world_bbox; // Float64Array [minx,miny,maxx,maxy]
    // Transfer the big columns' backing buffers (no copy across the boundary);
    // the small summary comes along by value.
    self.postMessage(
      {
        type: 'done',
        coords: coords.buffer,
        starts: starts.buffer,
        layers: layers.buffer,
        meta: meta.buffer,
        layer_set: layer_set.buffer,
        world_bbox: [world_bbox[0], world_bbox[1], world_bbox[2], world_bbox[3]],
        total_shapes: result.total_shapes,
        distinct_polys: result.distinct_polys,
        cell_defs: result.cell_defs,
        worker_heap_bytes: result.worker_heap_bytes,
        parse_ms: result.parse_ms,
      },
      [coords.buffer, starts.buffer, layers.buffer, meta.buffer, layer_set.buffer]
    );
    result.free();
  } catch (err) {
    self.postMessage({ type: 'error', message: String(err && err.message || err) });
  }
};
